const fs = require('fs');
const path = require('path');

const MANIFEST_NAME = 'backup-manifest.json';
const rootDir = __dirname;

const files = fs
  .readdirSync(rootDir, { withFileTypes: true })
  .filter(
    (entry) =>
      entry.isFile() && !entry.name.startsWith('.') && entry.name !== MANIFEST_NAME
  )
  .map((entry) => entry.name)
  .sort();

const manifest = { files };
fs.writeFileSync(
  path.join(rootDir, MANIFEST_NAME),
  `${JSON.stringify(manifest, null, 2)}\n`
);

console.log(`Wrote ${MANIFEST_NAME} (${files.length} file(s)):`);
for (const file of files) {
  console.log(`  ${file}`);
}

