const fs=require('fs');
const m=JSON.parse(fs.readFileSync('backup-manifest.json','utf8'));
const f=m.files;
console.log('keys in manifest:', JSON.stringify(Object.keys(m)));
console.log('has files array:', Array.isArray(f));
console.log('hidden/self excluded:', !f.some(x=>x.startsWith('.')||x==='backup-manifest.json'));
